import React, { useEffect, useState } from 'react'
import axios from 'axios'
import '../Counselling.css'
import {
  getAllCounsellors, createCounsellor, updateCounsellor, toggleCounsellorActive,
  getDeactivationPreview, deactivateCounsellor, AffectedSession, DeactivationResult,
} from '../API/CounsellorAPI'
import { getAllMappings, allocateCounsellor, CounsellorInstituteMapping } from '../API/CounsellorInstituteAPI'
import { getSlotsByCounsellor } from '../API/SlotAPI'
import { Modal } from 'react-bootstrap-v5'
import CounsellorForm, { COUNSELLOR_FORM_ID } from './components/CounsellorForm'
import AppointCounsellorModal from './components/AppointCounsellorModal'
import ManageSessionsModal from './components/ManageSessionsModal'
import CounsellorAvailabilityPanel from '../shared/CounsellorAvailabilityPanel'
import WeeklySchedulePanel from '../shared/WeeklySchedulePanel'
import { useRefreshInterval } from '../../../utils/useAutoRefresh'
import PageHeader from '../../../components/PageHeader'
import SearchableSelect from '../../../components/SearchableSelect'
import { useAuth } from '../../../modules/auth'

const API_URL = process.env.REACT_APP_API_URL

interface Counsellor {
  counsellorId: number
  id?: number
  name: string
  email: string
  phone?: string
  specializations?: string
  companyName?: string
  officeAddress?: string
  bio?: string
  isExternal?: boolean
  isActive?: boolean
  onboardingStatus?: string
  profileImageUrl?: string
}

/** Safely get the counsellor's ID (backend may return `id` or frontend may map `counsellorId`) */
function getCounsellorId(c: Counsellor): number {
  return c.counsellorId || c.id || 0
}

interface SlotData {
  id: number
  date: string
  startTime: string
  endTime: string
  durationMinutes: number
  status: string
}

const SlotsSection: React.FC<{ counsellor: Counsellor; onClose: () => void }> = ({ counsellor, onClose }) => {
  const [slots, setSlots] = useState<SlotData[]>([])
  const [loadingSlots, setLoadingSlots] = useState(true)

  useEffect(() => {
    setLoadingSlots(true)
    const today = new Date().toISOString().split('T')[0]
    const future = new Date()
    future.setDate(future.getDate() + 60)
    const end = future.toISOString().split('T')[0]

    getSlotsByCounsellor(getCounsellorId(counsellor), today, end)
      .then((res) => {
        const data: SlotData[] = Array.isArray(res.data) ? res.data : []
        setSlots(data.sort((a, b) => {
          const dc = a.date.localeCompare(b.date)
          return dc !== 0 ? dc : a.startTime.localeCompare(b.startTime)
        }))
      })
      .catch(() => setSlots([]))
      .finally(() => setLoadingSlots(false))
  }, [getCounsellorId(counsellor)])

  const slotsByDate = new Map<string, SlotData[]>()
  for (const s of slots) {
    const arr = slotsByDate.get(s.date) || []
    arr.push(s)
    slotsByDate.set(s.date, arr)
  }

  const formatDate = (d: string) => {
    try { return new Date(d + 'T00:00:00').toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short' }) }
    catch { return d }
  }

  const statusColors: Record<string, { bg: string; color: string }> = {
    AVAILABLE: { bg: '#D1FAE5', color: '#065F46' },
    REQUESTED: { bg: '#FEF3C7', color: '#92400E' },
    BOOKED: { bg: '#DBEAFE', color: '#1E40AF' },
    CANCELLED: { bg: '#FEE2E2', color: '#991B1B' },
  }

  return (
    <div className='cl-card' style={{ marginTop: 28, padding: 0, border: '2px solid var(--sp-border, #D1E5DF)', borderRadius: 10 }}>
      <div style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '16px 20px', borderBottom: '1px solid var(--sp-border, #D1E5DF)',
        background: 'var(--sp-bg, #F2F7F5)', borderRadius: '10px 10px 0 0',
      }}>
        <div>
          <div style={{ fontWeight: 700, fontSize: 15, color: 'var(--sp-text, #1A2B28)' }}>
            Slots — {counsellor.name}
          </div>
          <div style={{ fontSize: 12, color: 'var(--sp-muted, #5C7A72)', marginTop: 2 }}>
            {slots.length} upcoming slot(s)
          </div>
        </div>
        <button onClick={onClose} style={{
          background: 'none', border: 'none', cursor: 'pointer',
          color: 'var(--sp-muted, #5C7A72)', fontSize: 20, lineHeight: 1, padding: '0 4px',
        }} title='Close'>&times;</button>
      </div>

      <div style={{ padding: 20 }}>
        {loadingSlots ? (
          <div style={{ fontSize: 13, color: 'var(--sp-muted)', padding: '10px 0' }}>Loading...</div>
        ) : slots.length === 0 ? (
          <div style={{ fontSize: 13, color: 'var(--sp-muted)', padding: '10px 0' }}>
            No upcoming slots for this counsellor.
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 14, maxHeight: 400, overflowY: 'auto' }}>
            {Array.from(slotsByDate.entries()).map(([date, daySlots]) => (
              <div key={date}>
                <div style={{
                  fontSize: 13, fontWeight: 700, color: 'var(--sp-text, #1A2B28)',
                  marginBottom: 6, padding: '4px 0', borderBottom: '1px solid var(--sp-border, #D1E5DF)',
                }}>
                  {formatDate(date)}
                </div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
                  {daySlots.map((s) => {
                    const sc = statusColors[s.status] || { bg: '#F3F4F6', color: '#6B7280' }
                    return (
                      <div key={s.id} style={{
                        display: 'flex', alignItems: 'center', gap: 6, padding: '5px 10px',
                        background: sc.bg, borderRadius: 6, fontSize: 12,
                      }}>
                        <span style={{ fontWeight: 600, color: sc.color }}>
                          {s.startTime?.slice(0, 5)} - {s.endTime?.slice(0, 5)}
                        </span>
                        <span style={{ fontSize: 10, fontWeight: 600, color: sc.color, opacity: 0.7 }}>
                          {s.status}
                        </span>
                      </div>
                    )
                  })}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

const CounsellorManagementPage: React.FC = () => {
  const { currentUser } = useAuth()
  const [counsellors, setCounsellors] = useState<Counsellor[]>([])
  const [showForm, setShowForm] = useState(false)
  const [editingCounsellor, setEditingCounsellor] = useState<Counsellor | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [successMessage, setSuccessMessage] = useState<string | null>(null)
  const [togglingId, setTogglingId] = useState<number | null>(null)
  const [viewingSlotsCounsellor, setViewingSlotsCounsellor] = useState<Counsellor | null>(null)
  // The counsellor whose institutes + assessments are being set, if the Appoint wizard is open.
  const [appointingCounsellor, setAppointingCounsellor] = useState<Counsellor | null>(null)
  // The counsellor whose booked sessions are open for review and resending.
  const [managingSessionsCounsellor, setManagingSessionsCounsellor] = useState<Counsellor | null>(null)

  // Filters
  const [instituteMappings, setInstituteMappings] = useState<CounsellorInstituteMapping[]>([])
  const [institutes, setInstitutes] = useState<{ code: number; name: string }[]>([])
  const [filterInstitute, setFilterInstitute] = useState<number | ''>('')
  const [searchName, setSearchName] = useState('')

  // Selection & allocation
  const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set())
  const [showAllocateModal, setShowAllocateModal] = useState(false)
  const [allocating, setAllocating] = useState(false)

  // Availability modal: the counsellor's own availability workspace for a single
  // selection, or the bulk weekly-schedule form when several are ticked.
  const [showSlotModal, setShowSlotModal] = useState(false)
  // Office address used when an admin schedules in-person slots for one counsellor.
  const [scheduleOfficeAddress, setScheduleOfficeAddress] = useState('')

  // Deactivation confirmation: what suspending this counsellor would do to the
  // students booked with them, shown before anything is sent.
  const [deactivating, setDeactivating] = useState<Counsellor | null>(null)
  const [deactivationRows, setDeactivationRows] = useState<AffectedSession[] | null>(null)
  const [deactivationBusy, setDeactivationBusy] = useState(false)
  const [deactivationResult, setDeactivationResult] = useState<DeactivationResult | null>(null)


  // Phase 19: admin identity comes from the unified cookie session, not from
  // legacy localStorage JSON blobs (counsellor-portal + authUser) — they were
  // the audit hole in docs/AUTH_REDESIGN_PLAN.md §13 A13.
  const adminUserId: number = currentUser?.id ?? 0

  const loadCounsellors = async (opts?: { silent?: boolean }) => {
    if (!opts?.silent) { setLoading(true); setError(null) }
    try {
      const [counsellorRes, mappingRes, instituteRes] = await Promise.all([
        getAllCounsellors(),
        getAllMappings().catch(() => ({ data: [] })),
        axios.get(`${API_URL}/instituteDetail/get`).catch(() => ({ data: [] })),
      ])
      setCounsellors(counsellorRes.data ?? [])

      const mappings: CounsellorInstituteMapping[] = Array.isArray(mappingRes.data) ? mappingRes.data : []
      setInstituteMappings(mappings)

      const allInstitutes = Array.isArray(instituteRes.data) ? instituteRes.data : []
      setInstitutes(allInstitutes.map((i: any) => ({
        code: i.instituteCode || i.institute_code,
        name: i.instituteName || i.institute_name || `Institute ${i.instituteCode}`,
      })).sort((a, b) => a.name.trim().localeCompare(b.name.trim(), undefined, { sensitivity: 'base' })))

    } catch {
      if (!opts?.silent) setError('Failed to load counsellors. Please try again.')
    } finally {
      if (!opts?.silent) setLoading(false)
    }
  }

  useEffect(() => {
    loadCounsellors()
  }, [])
  useRefreshInterval(() => loadCounsellors({ silent: true }))

  const showSuccess = (msg: string) => {
    setSuccessMessage(msg)
    setTimeout(() => setSuccessMessage(null), 3500)
  }

  const [impersonatingId, setImpersonatingId] = useState<number | null>(null)

  const handleAddClick = () => {
    setEditingCounsellor(null)
    setShowForm(true)
  }

  const handleEditClick = (counsellor: Counsellor) => {
    setEditingCounsellor(counsellor)
    setShowForm(true)
  }

  const handleCancel = () => {
    setShowForm(false)
    setEditingCounsellor(null)
  }

  const handleSave = async (data: any) => {
    setError(null)
    try {
      if (editingCounsellor && getCounsellorId(editingCounsellor)) {
        await updateCounsellor(getCounsellorId(editingCounsellor), data)
        showSuccess('Counsellor updated successfully.')
      } else {
        await createCounsellor(data)
        showSuccess('Counsellor added successfully.')
      }
      setShowForm(false)
      setEditingCounsellor(null)
      await loadCounsellors()
    } catch {
      setError('Failed to save counsellor. Please try again.')
    }
  }

  const handleToggleActive = async (counsellor: Counsellor) => {
    // Activating is a harmless flag flip. Deactivating cancels other people's
    // sessions and emails them, so it goes through a confirmation showing exactly
    // who is affected before anything is sent.
    if (counsellor.isActive) {
      setDeactivating(counsellor)
      setDeactivationRows(null)
      setDeactivationResult(null)
      setError(null)
      try {
        const res = await getDeactivationPreview(getCounsellorId(counsellor))
        setDeactivationRows(Array.isArray(res.data) ? res.data : [])
      } catch {
        setDeactivationRows([])
        setError('Could not load the affected sessions — deactivating now would still settle them.')
      }
      return
    }

    setTogglingId(getCounsellorId(counsellor))
    setError(null)
    try {
      await toggleCounsellorActive(getCounsellorId(counsellor))
      showSuccess('Counsellor activated.')
      await loadCounsellors()
    } catch {
      setError('Failed to update counsellor status.')
    } finally {
      setTogglingId(null)
    }
  }

  const confirmDeactivate = async () => {
    if (!deactivating) return
    setDeactivationBusy(true)
    setError(null)
    try {
      const res = await deactivateCounsellor(getCounsellorId(deactivating), adminUserId)
      setDeactivationResult(res.data)
      await loadCounsellors()
    } catch (e: any) {
      const body = e?.response?.data
      setError(typeof body === 'string' ? body : body?.error || 'Failed to deactivate the counsellor.')
      setDeactivating(null)
    } finally {
      setDeactivationBusy(false)
    }
  }

  const toggleSelect = (id: number) => {
    setSelectedIds((prev) => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const toggleSelectAll = (filteredCounsellors: Counsellor[]) => {
    const allIds = filteredCounsellors.map(getCounsellorId)
    const allSelected = allIds.every((id) => selectedIds.has(id))
    if (allSelected) {
      setSelectedIds(new Set())
    } else {
      setSelectedIds(new Set(allIds))
    }
  }

  /**
   * Open the counsellor portal AS this counsellor, in a new tab.
   *
   * <p>Mirrors "Open as Student": the server mints a short-lived JWT, the new tab moves it
   * into its own sessionStorage, and the admin's session here is never touched. Closing that
   * tab ends the impersonation.
   *
   * <p>window.open is called BEFORE the await so the browser attributes it to the click and
   * does not block it as a popup.
   */
  const handleOpenAsCounsellor = async (counsellor: Counsellor) => {
    const id = getCounsellorId(counsellor)
    if (!id) return
    const tab = window.open('', '_blank')
    setImpersonatingId(id)
    try {
      const res = await axios.post(`${process.env.REACT_APP_API_URL}/admin/impersonate/counsellor/${id}`)
      const token = res?.data?.token
      if (!token) throw new Error('no token')
      const url = `${window.location.origin}/counsellor/impersonate?t=${encodeURIComponent(token)}`
      if (tab) tab.location.href = url
      else window.open(url, '_blank')
    } catch (err: any) {
      if (tab) tab.close()
      const msg = err?.response?.data
      alert(typeof msg === 'string' && msg
        ? msg
        : "Could not open this counsellor's portal. They may not have a login account.")
    } finally {
      setImpersonatingId(null)
    }
  }

  const openSlotModal = () => {
    setShowSlotModal(true)
    // In-person scheduling writes back to Counsellor.officeAddress, so seed the
    // field with what that counsellor already has (single selection only).
    const onlyId = selectedIds.size === 1 ? Array.from(selectedIds)[0] : null
    const onlyCounsellor = onlyId ? counsellors.find((c) => getCounsellorId(c) === onlyId) : null
    setScheduleOfficeAddress(onlyCounsellor?.officeAddress || '')
  }


  const handleAllocateToInstitute = async (instituteCode: number) => {
    setAllocating(true)
    setError(null)
    let successCount = 0
    let failCount = 0

    for (const id of selectedIds) {
      try {
        await allocateCounsellor(id, instituteCode, adminUserId || undefined)
        successCount++
      } catch {
        failCount++
      }
    }

    setAllocating(false)
    setShowAllocateModal(false)
    setSelectedIds(new Set())

    if (failCount === 0) {
      showSuccess(`${successCount} counsellor(s) allocated successfully.`)
    } else {
      showSuccess(`${successCount} allocated, ${failCount} failed (may already be allocated to another institute).`)
    }
    await loadCounsellors()
  }

  return (
    <div className="ph-page">
    <div style={{ padding: '24px 28px', background: 'var(--sp-bg, #F2F7F5)', minHeight: '100vh' }}>
      <PageHeader
        icon={<i className="bi bi-headset" />}
        title="Manage Counsellors"
        subtitle="Review, approve, and manage counsellor profiles"
        actions={selectedIds.size > 0 ? [
          { label: `Institute Allocation (${selectedIds.size})`, iconClass: 'bi-building', onClick: () => setShowAllocateModal(true), variant: 'primary' },
          { label: `Manage Availability (${selectedIds.size})`, iconClass: 'bi-calendar-plus', onClick: openSlotModal, variant: 'ghost' },
        ] : []}
      />

      {/* Allocation Modal */}
      {showAllocateModal && (
        <div style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          background: 'rgba(0,0,0,0.4)', zIndex: 1000,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }} onClick={() => !allocating && setShowAllocateModal(false)}>
          <div style={{
            background: '#fff', borderRadius: 12, padding: 28, width: 420, maxHeight: '80vh',
            overflowY: 'auto', boxShadow: '0 8px 32px rgba(0,0,0,0.15)',
          }} onClick={(e) => e.stopPropagation()}>
            <h3 style={{ margin: '0 0 6px', fontSize: 18, fontWeight: 700, color: '#1A2B28' }}>
              Allocate to Institute
            </h3>
            <p style={{ margin: '0 0 20px', fontSize: 13, color: '#5C7A72' }}>
              Select an institute to allocate {selectedIds.size} counsellor(s)
            </p>

            {allocating ? (
              <div style={{ textAlign: 'center', padding: '20px 0', color: '#5C7A72', fontSize: 14 }}>
                Allocating...
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                {institutes.map((inst) => (
                  <button
                    key={inst.code}
                    onClick={() => handleAllocateToInstitute(inst.code)}
                    style={{
                      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                      padding: '12px 16px', border: '1.5px solid #D1E5DF', borderRadius: 8,
                      background: '#fff', cursor: 'pointer', fontSize: 14, color: '#1A2B28',
                      fontWeight: 500, textAlign: 'left', transition: 'all 0.15s',
                    }}
                    onMouseEnter={(e) => { e.currentTarget.style.background = '#F0FFF4'; e.currentTarget.style.borderColor = '#0C6B5A' }}
                    onMouseLeave={(e) => { e.currentTarget.style.background = '#fff'; e.currentTarget.style.borderColor = '#D1E5DF' }}
                  >
                    <span>{inst.name}</span>
                    <svg width='16' height='16' viewBox='0 0 24 24' fill='none' stroke='#0C6B5A' strokeWidth='2'>
                      <polyline points='9 18 15 12 9 6' />
                    </svg>
                  </button>
                ))}
                {institutes.length === 0 && (
                  <div style={{ fontSize: 13, color: '#5C7A72', textAlign: 'center', padding: 16 }}>
                    No institutes found.
                  </div>
                )}
              </div>
            )}

            <button
              onClick={() => setShowAllocateModal(false)}
              disabled={allocating}
              style={{
                marginTop: 20, width: '100%', padding: '10px 0', fontSize: 13, fontWeight: 600,
                border: '1.5px solid #D1E5DF', borderRadius: 8, background: '#fff',
                color: '#5C7A72', cursor: 'pointer',
              }}
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* Slot Configuration Modal */}
      {showSlotModal && (
        <div style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          background: 'rgba(0,0,0,0.4)', zIndex: 1000,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }} onClick={() => setShowSlotModal(false)}>
          <div style={{
            background: '#fff', borderRadius: 12, padding: 28, maxHeight: '92vh',
            // The full availability workspace needs the counsellor portal's two-column
            // width; the bulk schedule form on its own is narrow.
            width: selectedIds.size === 1 ? 'min(1160px, 95vw)' : 580,
            overflowY: 'auto', boxShadow: '0 8px 32px rgba(0,0,0,0.15)',
          }} onClick={(e) => e.stopPropagation()}>
            <h3 style={{ margin: '0 0 6px', fontSize: 18, fontWeight: 700, color: '#1A2B28' }}>
              {selectedIds.size === 1 ? 'Manage Availability' : 'Add Weekly Schedule'}
            </h3>
            <p style={{ margin: '0 0 16px', fontSize: 13, color: '#5C7A72' }}>
              {(() => {
                const only = selectedIds.size === 1
                  ? counsellors.find((c) => getCounsellorId(c) === Array.from(selectedIds)[0])
                  : null
                return only ? `For ${only.name}` : `For ${selectedIds.size} selected counsellors`
              })()}
            </p>

            {selectedIds.size === 1 ? (
              // One counsellor: the full availability workspace they see in their
              // own portal — weekly schedule, upcoming slots, extra slots, blocking.
              <CounsellorAvailabilityPanel
                counsellorId={Array.from(selectedIds)[0]}
                asAdmin
                onChanged={() => loadCounsellors({ silent: true })}
              />
            ) : (
              // Several counsellors: only the recurring schedule can be applied in
              // bulk — slots and blocked dates belong to one counsellor at a time.
              <WeeklySchedulePanel
                counsellorIds={Array.from(selectedIds)}
                officeAddress={scheduleOfficeAddress}
                onOfficeAddressChange={setScheduleOfficeAddress}
                // So each group of existing schedules is headed by whose it is.
                counsellorNames={Object.fromEntries(
                  counsellors.map((c) => [getCounsellorId(c), c.name]),
                )}
                onChanged={() => loadCounsellors({ silent: true })}
              />
            )}

            <button
              onClick={() => setShowSlotModal(false)}
              style={{
                marginTop: 20, width: '100%', padding: '10px 0', fontSize: 13, fontWeight: 600,
                border: '1.5px solid #D1E5DF', borderRadius: 8, background: '#fff',
                color: '#5C7A72', cursor: 'pointer',
              }}
            >
              Close
            </button>
          </div>
        </div>
      )}

      {/* Error Banner */}
      {error && (
        <div
          style={{
            marginBottom: 16,
            padding: '12px 16px',
            background: '#FEE2E2',
            border: '1px solid #FECACA',
            borderRadius: 8,
            color: '#991B1B',
            fontSize: 14,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <span>{error}</span>
          <button
            onClick={() => setError(null)}
            style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#991B1B', fontSize: 16 }}
          >
            &times;
          </button>
        </div>
      )}

      {/* Success Banner */}
      {successMessage && (
        <div
          style={{
            marginBottom: 16,
            padding: '12px 16px',
            background: '#D1FAE5',
            border: '1px solid #A7F3D0',
            borderRadius: 8,
            color: '#065F46',
            fontSize: 14,
          }}
        >
          {successMessage}
        </div>
      )}

      {/* Filters */}
      <div className='cl-card' style={{ padding: '12px 20px', marginBottom: 16, display: 'flex', gap: 16, alignItems: 'center', flexWrap: 'wrap' }}>
        <input
          type='text'
          placeholder='Search by name...'
          value={searchName}
          onChange={(e) => setSearchName(e.target.value)}
          style={{
            padding: '6px 10px', border: '1px solid var(--sp-border, #D1E5DF)',
            borderRadius: 6, fontSize: 13, outline: 'none', width: 200, boxSizing: 'border-box',
          }}
        />
        <SearchableSelect
          options={institutes.map((i) => ({ value: String(i.code), label: i.name }))}
          value={filterInstitute === '' ? '' : String(filterInstitute)}
          onChange={(v) => setFilterInstitute(v ? Number(v) : '')}
          placeholder='All Institutes'
          style={{ minWidth: 200 }}
        />
        {(filterInstitute || searchName) && (
          <button
            onClick={() => { setFilterInstitute(''); setSearchName('') }}
            style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#E65100', fontSize: 13, fontWeight: 600 }}
          >
            Clear
          </button>
        )}
      </div>

      {/* Add / Edit counsellor.
          A dialog rather than a panel above the table: rendered inline it pushed the whole
          list down the page, so clicking Edit on a row scrolled that row out of sight and
          left no visual tie between the form and the counsellor being edited. */}
      <Modal show={showForm} onHide={handleCancel} size='lg' centered backdrop='static'>
        <Modal.Header>
          <Modal.Title>
            <h2 className='mb-0'>
              {editingCounsellor ? 'Edit Counsellor' : 'Add Counsellor'}
            </h2>
            {editingCounsellor && <small className='text-muted'>{editingCounsellor.name}</small>}
          </Modal.Title>
          <div
            className='btn btn-sm btn-icon btn-active-color-primary'
            onClick={handleCancel}
            style={{ cursor: 'pointer', fontSize: 22, lineHeight: 1 }}
          >
            &times;
          </div>
        </Modal.Header>
        <Modal.Body>
          <CounsellorForm counsellor={editingCounsellor} onSave={handleSave} />
        </Modal.Body>
        <Modal.Footer>
          <button type='button' className='btn btn-light' onClick={handleCancel}>
            Cancel
          </button>
          <button type='submit' form={COUNSELLOR_FORM_ID} className='btn btn-primary'>
            {editingCounsellor ? 'Save Changes' : 'Add Counsellor'}
          </button>
        </Modal.Footer>
      </Modal>

      {/* Table */}
      {(() => {
        // Filter counsellors by institute if filter is active
        let filteredCounsellors = counsellors
        if (filterInstitute) {
          filteredCounsellors = filteredCounsellors.filter((c) => {
            const cId = getCounsellorId(c)
            return instituteMappings.some(
              (m) => m.isActive && m.counsellor.id === cId && m.institute.instituteCode === filterInstitute
            )
          })
        }
        if (searchName.trim()) {
          const query = searchName.trim().toLowerCase()
          filteredCounsellors = filteredCounsellors.filter((c) =>
            c.name?.toLowerCase().includes(query)
          )
        }

        return loading ? (
        <div className='cl-card' style={{ textAlign: 'center', padding: '40px 20px', color: 'var(--sp-muted, #5C7A72)' }}>
          Loading counsellors...
        </div>
      ) : filteredCounsellors.length === 0 ? (
        <div className='cl-card' style={{ textAlign: 'center', padding: '40px 20px', color: 'var(--sp-muted, #5C7A72)' }}>
          {filterInstitute ? 'No counsellors found for the selected institute.' : 'No counsellors found.'}
        </div>
      ) : (
        <div className='cl-card' style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 14 }}>
            <thead>
              <tr style={{ borderBottom: '2px solid var(--sp-border, #D1E5DF)' }}>
                <th style={{ padding: '10px 14px', width: 40 }}>
                  <input
                    type='checkbox'
                    checked={filteredCounsellors.length > 0 && filteredCounsellors.every((c) => selectedIds.has(getCounsellorId(c)))}
                    onChange={() => toggleSelectAll(filteredCounsellors)}
                    style={{ width: 16, height: 16, cursor: 'pointer', accentColor: '#0C6B5A' }}
                  />
                </th>
                {['Name', 'Email', 'Specializations', 'Status', 'Actions'].map((col) => (
                  <th
                    key={col}
                    style={{
                      padding: '10px 14px',
                      textAlign: 'left',
                      fontWeight: 700,
                      fontSize: 12,
                      color: 'var(--sp-muted, #5C7A72)',
                      textTransform: 'uppercase',
                      letterSpacing: '0.04em',
                      whiteSpace: 'nowrap',
                    }}
                  >
                    {col}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filteredCounsellors.map((c, idx) => (
                <tr
                  key={getCounsellorId(c)}
                  style={{
                    borderBottom: '1px solid var(--sp-border, #D1E5DF)',
                    background: idx % 2 === 0 ? '#fff' : 'var(--sp-bg, #F2F7F5)',
                  }}
                >
                  {/* Checkbox */}
                  <td style={{ padding: '12px 14px', width: 40 }}>
                    <input
                      type='checkbox'
                      checked={selectedIds.has(getCounsellorId(c))}
                      onChange={() => toggleSelect(getCounsellorId(c))}
                      style={{ width: 16, height: 16, cursor: 'pointer', accentColor: '#0C6B5A' }}
                    />
                  </td>

                  {/* Name */}
                  <td style={{ padding: '12px 14px' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                      <div style={{
                        width: 36, height: 36, borderRadius: '50%', overflow: 'hidden',
                        background: '#E8F5E9', display: 'flex', alignItems: 'center',
                        justifyContent: 'center', flexShrink: 0, border: '1px solid #D1E5DF',
                      }}>
                        {c.profileImageUrl ? (
                          <img src={c.profileImageUrl} alt='' style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                        ) : (
                          <span style={{ fontSize: 14, fontWeight: 700, color: '#0C6B5A' }}>
                            {c.name?.charAt(0)?.toUpperCase() || '?'}
                          </span>
                        )}
                      </div>
                      <div>
                        <div style={{ fontWeight: 600, color: 'var(--sp-text, #1A2B28)' }}>{c.name}</div>
                        {c.isExternal && (
                          <div style={{ fontSize: 11, color: 'var(--sp-muted, #5C7A72)', marginTop: 1 }}>
                            External
                          </div>
                        )}
                      </div>
                    </div>
                  </td>

                  {/* Email */}
                  <td style={{ padding: '12px 14px', color: 'var(--sp-text, #1A2B28)' }}>
                    {c.email}
                  </td>

                  {/* Specializations */}
                  <td style={{ padding: '12px 14px', color: 'var(--sp-muted, #5C7A72)' }}>
                    {c.specializations || <span style={{ fontStyle: 'italic' }}>Not specified</span>}
                  </td>

                  {/* Status */}
                  <td style={{ padding: '12px 14px' }}>
                    {(() => {
                      const status = c.onboardingStatus || (c.isActive ? 'ACTIVE' : 'INACTIVE')
                      const colors: Record<string, { bg: string; color: string }> = {
                        ACTIVE: { bg: '#D1FAE5', color: '#065F46' },
                        PENDING: { bg: '#FEF3C7', color: '#92400E' },
                        SUSPENDED: { bg: '#FEE2E2', color: '#991B1B' },
                      }
                      const sc = colors[status] || { bg: '#F3F4F6', color: '#6B7280' }
                      return (
                        <span
                          style={{
                            display: 'inline-block',
                            padding: '3px 10px',
                            borderRadius: 999,
                            fontSize: 12,
                            fontWeight: 600,
                            background: sc.bg,
                            color: sc.color,
                          }}
                        >
                          {status}
                        </span>
                      )
                    })()}
                  </td>

                  {/* Actions */}
                  <td style={{ padding: '12px 14px' }}>
                    <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                      <button
                        className='cl-btn-outline'
                        style={{ fontSize: 12, padding: '5px 12px' }}
                        onClick={() => handleEditClick(c)}
                      >
                        Edit
                      </button>
                      <button
                        className={c.isActive ? 'cl-btn-warning' : 'cl-btn-primary'}
                        style={{ fontSize: 12, padding: '5px 12px' }}
                        disabled={togglingId === getCounsellorId(c)}
                        onClick={() => handleToggleActive(c)}
                      >
                        {togglingId === getCounsellorId(c)
                          ? '...'
                          : c.isActive
                          ? 'Deactivate'
                          : 'Activate'}
                      </button>
                      <button
                        className={
                          viewingSlotsCounsellor && getCounsellorId(viewingSlotsCounsellor) === getCounsellorId(c)
                            ? 'cl-btn-warning'
                            : 'cl-btn-outline'
                        }
                        style={{ fontSize: 12, padding: '5px 12px' }}
                        onClick={() => setViewingSlotsCounsellor((prev) =>
                          prev && getCounsellorId(prev) === getCounsellorId(c) ? null : c
                        )}
                      >
                        Slots
                      </button>
                      {/* Institutes + assessments in one pass — the pair the booking flow
                          requires before a student is offered this counsellor at all. */}
                      <button
                        className='cl-btn-outline'
                        style={{ fontSize: 12, padding: '5px 12px', color: '#1D4ED8', borderColor: '#BFDBFE' }}
                        onClick={() => setAppointingCounsellor(c)}
                        title='Choose the institutes and assessments this counsellor covers'
                      >
                        Appoint
                      </button>
                      {/* Every session booked with this counsellor, and the two resends —
                          the only place an admin can put a session's details, and the
                          student's report, back in front of either party. */}
                      <button
                        className='cl-btn-outline'
                        style={{ fontSize: 12, padding: '5px 12px', color: '#0F766E', borderColor: '#99F6E4' }}
                        onClick={() => setManagingSessionsCounsellor(c)}
                        title="Review this counsellor's sessions and resend the details to the student or counsellor"
                      >
                        Manage Sessions
                      </button>
                      <button
                        className='cl-btn-outline'
                        style={{ fontSize: 12, padding: '5px 12px', color: '#6D28D9', borderColor: '#DDD6FE' }}
                        onClick={() => handleOpenAsCounsellor(c)}
                        disabled={impersonatingId === getCounsellorId(c)}
                        title='Open the counsellor portal as this counsellor, in a new tab'
                      >
                        {impersonatingId === getCounsellorId(c) ? 'Opening…' : 'Open as Counsellor'}
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )
      })()}

      {/* Appoint wizard: institutes, then their assessments. */}
      {appointingCounsellor && (
        <AppointCounsellorModal
          show
          counsellorId={getCounsellorId(appointingCounsellor)}
          counsellorName={appointingCounsellor.name}
          institutes={institutes}
          assignedBy={adminUserId || undefined}
          onHide={() => setAppointingCounsellor(null)}
          onSaved={(message) => {
            setAppointingCounsellor(null)
            showSuccess(message)
            loadCounsellors()
          }}
        />
      )}

      {/* Sessions booked with this counsellor, with the student/counsellor resends. */}
      {managingSessionsCounsellor && (
        <ManageSessionsModal
          show
          counsellorId={getCounsellorId(managingSessionsCounsellor)}
          counsellorName={managingSessionsCounsellor.name}
          onHide={() => setManagingSessionsCounsellor(null)}
        />
      )}

      {/* Slots Modal */}
      {viewingSlotsCounsellor && (
        <div style={{
          position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
          background: 'rgba(0,0,0,0.4)', zIndex: 1000,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }} onClick={() => setViewingSlotsCounsellor(null)}>
          <div style={{
            background: '#fff', borderRadius: 12, width: 560, maxHeight: '85vh',
            overflowY: 'auto', boxShadow: '0 8px 32px rgba(0,0,0,0.15)',
          }} onClick={(e) => e.stopPropagation()}>
            <SlotsSection
              counsellor={viewingSlotsCounsellor}
              onClose={() => setViewingSlotsCounsellor(null)}
            />
          </div>
        </div>
      )}
    </div>

      {/* Deactivation confirmation — what it will do, before it does it */}
      {deactivating && (
        <div
          onClick={() => !deactivationBusy && setDeactivating(null)}
          style={{
            position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.45)',
            zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center',
            padding: 20,
          }}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              width: '100%', maxWidth: 680, maxHeight: '85vh', overflow: 'hidden',
              background: '#fff', borderRadius: 14, boxShadow: '0 24px 48px rgba(0,0,0,0.2)',
              display: 'flex', flexDirection: 'column',
            }}
          >
            <div style={{
              padding: '16px 20px', borderBottom: '1px solid var(--sp-border, #D1E5DF)',
              display: 'flex', alignItems: 'center', justifyContent: 'space-between',
            }}>
              <div>
                <div style={{ fontSize: 16, fontWeight: 700, color: 'var(--sp-text, #1A2B28)' }}>
                  {deactivationResult ? 'Counsellor deactivated' : 'Deactivate counsellor'}
                </div>
                <div style={{ fontSize: 12, color: 'var(--sp-muted, #5C7A72)', marginTop: 2 }}>
                  {deactivating.name} · {deactivating.email}
                </div>
              </div>
              <button
                onClick={() => setDeactivating(null)}
                disabled={deactivationBusy}
                style={{
                  border: '1px solid var(--sp-border, #D1E5DF)', background: '#fff',
                  borderRadius: 8, cursor: 'pointer', padding: '4px 10px',
                  fontSize: 18, color: '#6B7280', lineHeight: 1,
                }}
                aria-label='Close'
              >
                &times;
              </button>
            </div>

            <div style={{ padding: 20, overflowY: 'auto' }}>
              {deactivationResult ? (
                <>
                  <div style={{
                    padding: '10px 14px', background: '#D1FAE5', border: '1px solid #A7F3D0',
                    borderRadius: 8, color: '#065F46', fontSize: 13, marginBottom: 14,
                  }}>
                    {deactivationResult.counsellorName} can no longer sign in or be booked.{' '}
                    {deactivationResult.parked > 0 && (
                      <>{deactivationResult.parked} student{deactivationResult.parked === 1 ? '' : 's'} sent a rebooking link. </>
                    )}
                    {deactivationResult.cancelled > 0 && (
                      <>{deactivationResult.cancelled} session{deactivationResult.cancelled === 1 ? '' : 's'} cancelled — the team needs to follow up. </>
                    )}
                    {deactivationResult.failed > 0 && (
                      <strong>{deactivationResult.failed} could not be settled — check them manually.</strong>
                    )}
                  </div>
                  <div style={{ fontSize: 12.5, color: 'var(--sp-muted, #5C7A72)' }}>
                    The counsellor has been emailed, and the configured admins have the full list
                    of affected students.
                  </div>
                </>
              ) : deactivationRows === null ? (
                <div style={{ textAlign: 'center', padding: '28px 0', color: 'var(--sp-muted, #5C7A72)', fontSize: 13 }}>
                  Checking their upcoming sessions...
                </div>
              ) : deactivationRows.length === 0 ? (
                <p style={{ fontSize: 13, lineHeight: 1.65, color: 'var(--sp-text, #1A2B28)', margin: 0 }}>
                  This counsellor has no upcoming sessions, so no student is affected. They will
                  lose access to the counsellor portal, their remaining slots stop being offered
                  to students, and they will be emailed to say the account has been deactivated.
                </p>
              ) : (
                <>
                  <p style={{ fontSize: 13, lineHeight: 1.65, color: 'var(--sp-text, #1A2B28)', margin: '0 0 14px' }}>
                    <strong>{deactivationRows.length}</strong> upcoming session
                    {deactivationRows.length === 1 ? '' : 's'} will be taken off the calendar.
                    Students with another counsellor covering their assessment are emailed a link
                    to pick a new time; the rest are told the team will be in touch, and appear in
                    the admin alert as needing follow-up.
                  </p>
                  <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
                    <thead>
                      <tr style={{ borderBottom: '2px solid var(--sp-border, #D1E5DF)' }}>
                        {['Student', 'When', 'What happens'].map((c) => (
                          <th key={c} style={{
                            padding: '8px 10px', textAlign: 'left', fontWeight: 700, fontSize: 11,
                            color: 'var(--sp-muted, #5C7A72)', textTransform: 'uppercase',
                            letterSpacing: '0.04em',
                          }}>{c}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody>
                      {deactivationRows.map((r, i) => (
                        <tr key={r.appointmentId} style={{
                          borderBottom: '1px solid var(--sp-border, #D1E5DF)',
                          background: i % 2 === 0 ? '#fff' : 'var(--sp-bg, #F2F7F5)',
                        }}>
                          <td style={{ padding: '9px 10px' }}>
                            <div style={{ fontWeight: 600 }}>{r.studentName || 'Student'}</div>
                            <div style={{ fontSize: 11, color: 'var(--sp-muted, #5C7A72)', marginTop: 2 }}>
                              {r.studentEmail || '—'}
                            </div>
                          </td>
                          <td style={{ padding: '9px 10px', whiteSpace: 'nowrap' }}>
                            {r.date || '—'}
                            <div style={{ fontSize: 11, color: 'var(--sp-muted, #5C7A72)', marginTop: 2 }}>
                              {(r.startTime || '').slice(0, 5)}
                            </div>
                          </td>
                          <td style={{ padding: '9px 10px' }}>
                            <span className='cl-badge' style={r.hasAlternative
                              ? { background: '#DBEAFE', color: '#1E40AF' }
                              : { background: '#FEF3C7', color: '#92400E' }}>
                              {r.hasAlternative ? 'Rebooking link' : 'Needs follow-up'}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </>
              )}
            </div>

            <div style={{
              padding: '14px 20px', borderTop: '1px solid var(--sp-border, #D1E5DF)',
              display: 'flex', justifyContent: 'flex-end', gap: 8,
            }}>
              {deactivationResult ? (
                <button className='cl-btn-primary' style={{ fontSize: 13 }} onClick={() => setDeactivating(null)}>
                  Done
                </button>
              ) : (
                <>
                  <button
                    className='cl-btn-outline' style={{ fontSize: 13 }}
                    onClick={() => setDeactivating(null)} disabled={deactivationBusy}
                  >
                    Cancel
                  </button>
                  <button
                    className='cl-btn-danger' style={{ fontSize: 13 }}
                    onClick={confirmDeactivate}
                    disabled={deactivationBusy || deactivationRows === null}
                  >
                    {deactivationBusy ? 'Deactivating...' : 'Deactivate & notify'}
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
      )}

    </div>
  )
}

export default CounsellorManagementPage
